const starArrows = [];
const starMats = [];
for (let i = 0; i < 8; i++) {
  const angle = i * Math.PI / 4;
  const mat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
  const arrow = makeArrow(1.0, 0.045, 0xcc2222, 0.22, 0.09);
  arrow.traverse(o => { if (o.isMesh) o.material = mat; });
  arrow.rotation.x = angle;
  arrow.position.copy(starCenter);
  scene.add(arrow);
  starArrows.push(arrow);
  starMats.push(mat);
  const deg = i * 45;
  registerInteractive(arrow, {
    title: `E-field at ${deg}°`,
    body: `This E-field vector points at ${deg}° from vertical in the transverse plane. Click to isolate it and see how the filter decomposes it into a transmitted (parallel) and absorbed (perpendicular) component. Transmitted amplitude = E₀·cos(θ).`,
    tooltip: `E at ${deg}° — click to decompose`,
    onClick: () => selectArrow(i)
  });
}

// 3. Filter disk + rim
const filterGroup = new THREE.Group();
const diskMat = new THREE.MeshBasicMaterial({ color: 0xf0d9a8, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
const disk = new THREE.Mesh(new THREE.CircleGeometry(1.15, 32), diskMat);
disk.rotation.y = Math.PI / 2;
filterGroup.add(disk);
const rimMat = new THREE.MeshBasicMaterial({ color: 0xe0a050, transparent: true, opacity: 1 });
const rim = new THREE.Mesh(new THREE.TorusGeometry(1.15, 0.04, 8, 32), rimMat);
rim.rotation.y = Math.PI / 2;
filterGroup.add(rim);
filterGroup.position.set(1.0, 0, 0);
scene.add(filterGroup);

// 4. Axis double-headed arrow
const axisGroup = new THREE.Group();
const axisMat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 1 });
const axisArrow = makeDoubleArrow(2.0, 0.03, 0x111111, 0.2, 0.07);
axisArrow.traverse(o => { if (o.isMesh) o.material = axisMat; });
axisGroup.add(axisArrow);
axisGroup.position.set(1.0, 0, 0);
scene.add(axisGroup);

// 5. Transmitted double-headed arrow
const transGroup = new THREE.Group();
const transMat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
const transArrow = makeDoubleArrow(1.8, 0.045, 0xcc2222, 0.22, 0.09);
transArrow.traverse(o => { if (o.isMesh) o.material = transMat; });
transGroup.add(transArrow);
transGroup.position.set(2.8, 0, 0);
scene.add(transGroup);

// 6. Decomposition arrows (hidden)
const greenMat = new THREE.MeshBasicMaterial({ color: 0x22aa44, transparent: true, opacity: 1 });
const greenGroup = new THREE.Group();
const greenArrow = makeArrow(1.0, 0.04, 0x22aa44, 0.2, 0.08);
greenArrow.traverse(o => { if (o.isMesh) o.material = greenMat; });
greenGroup.add(greenArrow);
greenGroup.visible = false;
scene.add(greenGroup);

const greyMat = new THREE.MeshBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.4 });
const greyGroup = new THREE.Group();
const greyArrow = makeArrow(1.0, 0.04, 0x999999, 0.2, 0.08);
greyArrow.traverse(o => { if (o.isMesh) o.material = greyMat; });
greyGroup.add(greyArrow);
greyGroup.visible = false;
scene.add(greyGroup);

// 7. Wavy leaders
const leaderFilter = makeWavyLeader(
  new THREE.Vector3(1.0, 1.7, 0), new THREE.Vector3(1.0, 1.2, 0)
);
scene.add(leaderFilter);

const leaderAxis = makeWavyLeader(
  new THREE.Vector3(1.6, 1.3, 0), new THREE.Vector3(1.05, 0.9, 0)
);
scene.add(leaderAxis);

const leaderPolDir = makeWavyLeader(
  new THREE.Vector3(3.5, 1.0, 0), new THREE.Vector3(2.85, 0.7, 0)
);
scene.add(leaderPolDir);

const leaderRayDir = makeWavyLeader(
  new THREE.Vector3(3.5, -0.6, 0), new THREE.Vector3(3.3, -0.15, 0)
);
scene.add(leaderRayDir);

// ═══ LABELS ═══
// E labels on starburst arrows 0°, 45°, 90°, 135°
const eLabelPositions = [
  new THREE.Vector3(-1.5, 1.25, 0),
  new THREE.Vector3(-1.5, 0.9, 0.9),
  new THREE.Vector3(-1.5, 0, 1.25),
  new THREE.Vector3(-1.5, -0.9, 0.9)
];
for (let i = 0; i < 4; i++) {
  addLabel('E&#8407;', eLabelPositions[i], { fontSize: '14px', bold: true, color: '#111' });
}

addLabel('Random polarization', new THREE.Vector3(-1.5, 1.65, 0), { fontSize: '13px', bold: true });
addLabel('Direction of ray<br>(of propagation)', new THREE.Vector3(2.8, -0.55, 0), { fontSize: '12px' });
addLabel('Polarizing filter', new THREE.Vector3(1.0, 1.85, 0), { fontSize: '13px', bold: true });
addLabel('Axis', new THREE.Vector3(1.7, 1.4, 0), { fontSize: '13px', bold: true });

const lblTransE = addLabel('E&#8407;', new THREE.Vector3(3.1, 0.9, 0), { fontSize: '14px', bold: true, color: '#cc2222' });
const lblPolDir = addLabel('Polarization<br>direction', new THREE.Vector3(3.6, 1.15, 0), { fontSize: '12px' });
addLabel('Direction<br>of ray', new THREE.Vector3(3.6, -0.7, 0), { fontSize: '12px' });

// ═══ STATE & UPDATE ═══
let currentMode = 'unpolarized'; // 'unpolarized' | 'after'
let selectedArrowIdx = -1;

function getAxisDir() {
  const a = parseFloat(document.getElementById('filterAxisAngle').value) * Math.PI / 180;
  return new THREE.Vector3(0, Math.sin(a), Math.cos(a));
}

function updateScene() {
  const aDeg = parseFloat(document.getElementById('filterAxisAngle').value);
  const aRad = aDeg * Math.PI / 180;
  document.getElementById('axisAngleVal').textContent = aDeg + '°';

  // Rotate axis and transmitted arrows
  const rotAngle = Math.PI / 2 - aRad;
  axisGroup.rotation.x = rotAngle;
  transGroup.rotation.x = rotAngle;

  // Update dynamic label positions
  const dAxis = getAxisDir();
  const transTip = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 1.05);
  lblTransE.pos.copy(transTip).add(new THREE.Vector3(0.15, 0.1, 0));

  const polDirPos = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 0.7).add(new THREE.Vector3(0.7, 0.3, 0));
  lblPolDir.pos.copy(polDirPos);

  // View mode opacities
  if (currentMode === 'unpolarized') {
    starMats.forEach(m => { m.opacity = 1; });
    diskMat.opacity = 0.12;
    rimMat.opacity = 0.12;
    axisMat.opacity = 0.12;
    transMat.opacity = 0.12;
    greenMat.opacity = 0.12;
    greyMat.opacity = 0.08;
    leaderFilter.visible = false;
    leaderAxis.visible = false;
    leaderPolDir.visible = false;
    leaderRayDir.visible = false;
  } else {
    starMats.forEach((m, i) => {
      m.opacity = (i === selectedArrowIdx) ? 1 : 0.18;
    });
    diskMat.opacity = 0.55;
    rimMat.opacity = 1;
    axisMat.opacity = 1;
    transMat.opacity = 1;
    greenMat.opacity = 1;
    greyMat.opacity = 0.4;
    leaderFilter.visible = true;
    leaderAxis.visible = true;
    leaderPolDir.visible = true;
    leaderRayDir.visible = true;
  }

  // Update decomposition if selected
  updateDecomposition();
}

function updateDecomposition() {
  if (selectedArrowIdx < 0 || currentMode !== 'after') {
    greenGroup.visible = false;
    greyGroup.visible = false;
    return;
  }

  const theta = selectedArrowIdx * Math.PI / 4;
  const dArrow = new THREE.Vector3(0, Math.cos(theta), Math.sin(theta));
  const dAxis = getAxisDir();

  const dot = dArrow.dot(dAxis);
  const parallel = dAxis.clone().multiplyScalar(dot);
  const perp = dArrow.clone().sub(parallel);
  const parallelMag = Math.abs(dot);
  const perpMag = perp.length();

  // Green arrow at filter, along axis
  greenGroup.visible = parallelMag > 0.02;
