    diskMat.opacity = 0.55;
    rimMat.opacity = 1;
    axisMat.opacity = 1;
    transMat.opacity = 1;
    greenMat.opacity = 1;
    greyMat.opacity = 0.4;
    leaderFilter.visible = true;
    leaderAxis.visible = true;
    leaderPolDir.visible = true;
    leaderRayDir.visible = true;
  }

  // Update decomposition if selected
  updateDecomposition();
}

function updateDecomposition() {
  if (selectedArrowIdx < 0 || currentMode !== 'after') {
    greenGroup.visible = false;
    greyGroup.visible = false;
    return;
  }

  const theta = selectedArrowIdx * Math.PI / 4;
  const dArrow = new THREE.Vector3(0, Math.cos(theta), Math.sin(theta));
  const dAxis = getAxisDir();

  const dot = dArrow.dot(dAxis);
  const parallel = dAxis.clone().multiplyScalar(dot);
  const perp = dArrow.clone().sub(parallel);
  const parallelMag = Math.abs(dot);
  const perpMag = perp.length();

  // Green arrow at filter, along axis
  greenGroup.visible = parallelMag > 0.02;
  if (greenGroup.visible) {
    greenGroup.position.set(1.0, 0, 0);
    const targetDir = dot >= 0 ? dAxis.clone() : dAxis.clone().negate();
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), targetDir.normalize());
    greenGroup.quaternion.copy(q);
    greenGroup.scale.set(1, Math.max(0.05, parallelMag), 1);
  }

  // Grey arrow at starburst, along perp
  greyGroup.visible = perpMag > 0.02;
  if (greyGroup.visible) {
    greyGroup.position.copy(starCenter);
    const q2 = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), perp.clone().normalize());
    greyGroup.quaternion.copy(q2);
    greyGroup.scale.set(1, Math.max(0.05, perpMag), 1);
  }
}

function selectArrow(idx) {
  if (selectedArrowIdx === idx) {
    selectedArrowIdx = -1;
  } else {
    selectedArrowIdx = idx;
    if (currentMode !== 'after') {
