// ═══ DEMO STEPS ═══
let _tweenRAF = null;
function tweenSlider(target, duration, cb) {
  const slider = document.getElementById('filterAxisAngle');
  const start = parseFloat(slider.value);
  const t0 = performance.now();
  if (_tweenRAF) cancelAnimationFrame(_tweenRAF);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const ease = t * (2 - t);
    slider.value = Math.round(start + (target - start) * ease);
    updateScene();
    if (t < 1) _tweenRAF = requestAnimationFrame(tick);
    else if (cb) cb();
  }
  tick();
}

function goToStep(n) {
