// @FIGURE_CODE_BEGIN
// ── Element specs ──
// blue ray → Line (-3,0,0)→(3.7,0,0) + ConeGeometry(0.08,0.3) arrowhead at (4,0,0) rotZ=-90°, color #1f8fb0
// starburst → 8× (CylinderGeometry(0.045,0.045,0.78,8) + ConeGeometry(0.09,0.22,8)) red #cc2222, len 1.0, at (-1.5,0,0), rotX = i*45°
// E labels → addLabel with HTML vector arrow at tips of arrows 0°,45°,90°,135°
// 'Random polarization' → addLabel (-1.5,1.6,0)
// 'Direction of ray (of propagation)' → addLabel (3.2,-0.5,0)
// filter disk → CircleGeometry(1.15,32) tan #f0d9a8 op0.55 + TorusGeometry(1.15,0.04,8,32) rim #e0a050, at (1,0,0) rotY=90°
// axis arrow → double-headed (2×ConeGeometry(0.07,0.2,8)+CylinderGeometry(0.03,0.03,1.6,8)) black #111, totalLen 2.0, at (1,0,0)
// transmitted arrow → double-headed red #cc2222, totalLen 1.8, at (2.8,0,0)
// 'Polarizing filter' → addLabel (1.0,1.7,0) + wavy leader line
// 'Axis' → addLabel dynamic + wavy leader
// 'E' transmitted → addLabel dynamic with vector arrow HTML
// 'Polarization direction' → addLabel dynamic + wavy leader
// 'Direction of ray' beyond → addLabel (3.2,-0.4,0.3)
// green decomp → makeArrow(1.0) #22aa44 at filter, along axis
// grey decomp → makeArrow(1.0) #999999 op0.4 at starburst, perp direction

// ═══ HELPERS ═══
const E_VEC_HTML = '<span style="position:relative;display:inline-block;font-weight:bold">E<span style="position:absolute;top:-0.65em;left:0.15em;font-size:0.55em;font-weight:normal">→</span></span>';

function makeArrow(length, radius, color, headLen, headRad, opacity) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: opacity ?? 1 });
  const shaftLen = Math.max(0.01, length - headLen);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 8), mat);
  shaft.position.y = shaftLen / 2;
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  head.position.y = shaftLen + headLen / 2;
  g.add(head);
  return g;
}

function makeDoubleArrow(totalLen, radius, color, headLen, headRad, opacity) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: opacity ?? 1 });
  const shaftLen = Math.max(0.01, totalLen - 2 * headLen);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 8), mat);
  g.add(shaft);
  const hUp = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  hUp.position.y = shaftLen / 2 + headLen / 2;
  g.add(hUp);
  const hDn = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  hDn.rotation.z = Math.PI;
  hDn.position.y = -(shaftLen / 2 + headLen / 2);
  g.add(hDn);
  return g;
}

function makeWavyLeader(start, end, color) {
  const pts = [];
  const n = 24;
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  dir.normalize();
  let perp = new THREE.Vector3(0, 0, 1).cross(dir);
  if (perp.lengthSq() < 0.01) perp = new THREE.Vector3(0, 1, 0).cross(dir);
  perp.normalize();
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const p = start.clone().lerp(end, t);
    const wave = Math.sin(t * Math.PI * 4) * 0.06 * Math.sin(t * Math.PI);
    p.addScaledVector(perp, wave);
    pts.push(p);
  }
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geom, new THREE.LineBasicMaterial({ color: color ?? 0x111111 }));
}

// ═══ BUILD GEOMETRY ═══

// 1. Blue propagation ray
const rayPts = [new THREE.Vector3(-3, 0, 0), new THREE.Vector3(3.7, 0, 0)];
const rayLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(rayPts),
  new THREE.LineBasicMaterial({ color: 0x1f8fb0 })
);
scene.add(rayLine);

const rayHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.08, 0.3, 8),
  new THREE.MeshBasicMaterial({ color: 0x1f8fb0 })
);
rayHead.rotation.z = -Math.PI / 2;
rayHead.position.set(4, 0, 0);
scene.add(rayHead);

// 2. Starburst arrows
const starCenter = new THREE.Vector3(-1.5, 0, 0);
const starArrows = [];
const starMats = [];
for (let i = 0; i < 8; i++) {
  const angle = i * Math.PI / 4;
  const mat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
  const arrow = makeArrow(1.0, 0.045, 0xcc2222, 0.22, 0.09);
  arrow.traverse(o => { if (o.isMesh) o.material = mat; });
  arrow.rotation.x = angle;
  arrow.position.copy(starCenter);
  scene.add(arrow);
  starArrows.push(arrow);
  starMats.push(mat);
  const deg = i * 45;
  registerInteractive(arrow, {
    title: `E-field at ${deg}°`,
    body: `This E-field vector points at ${deg}° from vertical in the transverse plane. Click to isolate it and see how the filter decomposes it into a transmitted (parallel) and absorbed (perpendicular) component. Transmitted amplitude = E₀·cos(θ).`,
    tooltip: `E at ${deg}° — click to decompose`,
    onClick: () => selectArrow(i)
  });
}

// 3. Filter disk + rim
const filterGroup = new THREE.Group();
const diskMat = new THREE.MeshBasicMaterial({ color: 0xf0d9a8, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
const disk = new THREE.Mesh(new THREE.CircleGeometry(1.15, 32), diskMat);
disk.rotation.y = Math.PI / 2;
filterGroup.add(disk);
const rimMat = new THREE.MeshBasicMaterial({ color: 0xe0a050, transparent: true, opacity: 1 });
const rim = new THREE.Mesh(new THREE.TorusGeometry(1.15, 0.04, 8, 32), rimMat);
rim.rotation.y = Math.PI / 2;
filterGroup.add(rim);
filterGroup.position.set(1.0, 0, 0);
scene.add(filterGroup);

// 4. Axis double-headed arrow
const axisGroup = new THREE.Group();
const axisMat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 1 });
const axisArrow = makeDoubleArrow(2.0, 0.03, 0x111111, 0.2, 0.07);
axisArrow.traverse(o => { if (o.isMesh) o.material = axisMat; });
axisGroup.add(axisArrow);
axisGroup.position.set(1.0, 0, 0);
scene.add(axisGroup);

// 5. Transmitted double-headed arrow
const transGroup = new THREE.Group();
const transMat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
const transArrow = makeDoubleArrow(1.8, 0.045, 0xcc2222, 0.22, 0.09);
transArrow.traverse(o => { if (o.isMesh) o.material = transMat; });
transGroup.add(transArrow);
transGroup.position.set(2.8, 0, 0);
scene.add(transGroup);

// 6. Decomposition arrows (hidden initially)
const greenMat = new THREE.MeshBasicMaterial({ color: 0x22aa44, transparent: true, opacity: 1 });
const greenGroup = new THREE.Group();
const greenArrow = makeArrow(1.0, 0.04, 0x22aa44, 0.2, 0.08);
greenArrow.traverse(o => { if (o.isMesh) o.material = greenMat; });
greenGroup.add(greenArrow);
greenGroup.visible = false;
scene.add(greenGroup);

const greyMat = new THREE.MeshBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.5 });
const greyGroup = new THREE.Group();
const greyArrow = makeArrow(1.0, 0.04, 0x999999, 0.2, 0.08);
greyArrow.traverse(o => { if (o.isMesh) o.material = greyMat; });
greyGroup.add(greyArrow);
greyGroup.visible = false;
scene.add(greyGroup);

// 7. Wavy leaders (always visible)
const leaderFilter = makeWavyLeader(
  new THREE.Vector3(1.0, 1.7, 0), new THREE.Vector3(1.0, 1.2, 0)
);
scene.add(leaderFilter);

const leaderAxis = makeWavyLeader(
  new THREE.Vector3(1.6, 1.3, 0), new THREE.Vector3(1.05, 0.9, 0)
);
scene.add(leaderAxis);

const leaderPolDir = makeWavyLeader(
  new THREE.Vector3(3.5, 1.0, 0), new THREE.Vector3(2.85, 0.7, 0)
);
scene.add(leaderPolDir);

const leaderRayDir = makeWavyLeader(
  new THREE.Vector3(3.5, -0.6, 0), new THREE.Vector3(3.3, -0.15, 0)
);
scene.add(leaderRayDir);

// ═══ LABELS ═══
// E labels on starburst arrows 0°, 45°, 90°, 135°
const eLabelPositions = [
  new THREE.Vector3(-1.5, 1.25, 0),
  new THREE.Vector3(-1.5, 0.9, 0.9),
  new THREE.Vector3(-1.5, 0, 1.25),
  new THREE.Vector3(-1.5, -0.9, 0.9)
];
for (let i = 0; i < 4; i++) {
  addLabel(E_VEC_HTML, eLabelPositions[i], { fontSize: '14px', color: '#111' });
}

addLabel('Random polarization', new THREE.Vector3(-1.5, 1.65, 0), { fontSize: '13px', bold: true });
addLabel('Direction of ray<br>(of propagation)', new THREE.Vector3(2.8, -0.55, 0), { fontSize: '12px' });
addLabel('Polarizing filter', new THREE.Vector3(1.0, 1.85, 0), { fontSize: '13px', bold: true });
addLabel('Axis', new THREE.Vector3(1.7, 1.4, 0), { fontSize: '13px', bold: true });

const lblTransE = addLabel(E_VEC_HTML, new THREE.Vector3(3.1, 0.9, 0), { fontSize: '14px', color: '#cc2222' });
const lblPolDir = addLabel('Polarization<br>direction', new THREE.Vector3(3.6, 1.15, 0), { fontSize: '12px' });
addLabel('Direction<br>of ray', new THREE.Vector3(3.6, -0.7, 0), { fontSize: '12px' });

// ═══ STATE & UPDATE ═══
let currentMode = 'unpolarized';
let selectedArrowIdx = -1;

function getAxisDir() {
  const a = parseFloat(document.getElementById('filterAxisAngle').value) * Math.PI / 180;
  return new THREE.Vector3(0, Math.cos(a), Math.sin(a));
}

function updateScene() {
  const aDeg = parseFloat(document.getElementById('filterAxisAngle').value);
  const aRad = aDeg * Math.PI / 180;
  document.getElementById('axisAngleVal').textContent = aDeg + '°';

  // Rotate axis and transmitted arrows
  const rotAngle = aRad;
  axisGroup.rotation.x = rotAngle;
  transGroup.rotation.x = rotAngle;

  // Update dynamic label positions
  const dAxis = getAxisDir();
  const transTip = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 1.05);
  lblTransE.pos.copy(transTip).add(new THREE.Vector3(0.15, 0.1, 0));

  const polDirPos = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 0.7).add(new THREE.Vector3(0.7, 0.3, 0));
  lblPolDir.pos.copy(polDirPos);

  // View mode opacities — show everything in both modes, just adjust emphasis
  if (currentMode === 'unpolarized') {
    starMats.forEach(m => { m.opacity = 1; });
    diskMat.opacity = 0.45;
    rimMat.opacity = 0.7;
    axisMat.opacity = 0.6;
    transMat.opacity = 0.5;
    greenMat.opacity = 0.3;
    greyMat.opacity = 0.2;
  } else {
    starMats.forEach((m, i) => {
      m.opacity = (i === selectedArrowIdx) ? 1 : 0.25;
    });
    diskMat.opacity = 0.55;
    rimMat.opacity = 1;
    axisMat.opacity = 1;
    transMat.opacity = 1;
    greenMat.opacity = 1;
    greyMat.opacity = 0.5;
  }

  // Leaders always visible
  leaderFilter.visible = true;
  leaderAxis.visible = true;
  leaderPolDir.visible = true;
  leaderRayDir.visible = true;

  updateDecomposition();
}

function updateDecomposition() {
  if (selectedArrowIdx < 0) {
    greenGroup.visible = false;
    greyGroup.visible = false;
    return;
  }

  const theta = selectedArrowIdx * Math.PI / 4;
  const dArrow = new THREE.Vector3(0, Math.cos(theta), Math.sin(theta));
  const dAxis = getAxisDir();

  const dot = dArrow.dot(dAxis);
  const parallel = dAxis.clone().multiplyScalar(dot);
  const perp = dArrow.clone().sub(parallel);
  const parallelMag = Math.abs(dot);
  const perpMag = perp.length();

  // Green arrow at filter, along axis
  greenGroup.visible = parallelMag > 0.02;
  if (greenGroup.visible) {
    greenGroup.position.set(1.0, 0, 0);
    const targetDir = dot >= 0 ? dAxis.clone() : dAxis.clone().negate();
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), targetDir.normalize());
    greenGroup.quaternion.copy(q);
    greenGroup.scale.set(1, Math.max(0.05, parallelMag), 1);
  }

  // Grey arrow at starburst, along perp
  greyGroup.visible = perpMag > 0.02;
  if (greyGroup.visible) {
    greyGroup.position.copy(starCenter);
    const q2 = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), perp.clone().normalize());
    greyGroup.quaternion.copy(q2);
    greyGroup.scale.set(1, Math.max(0.05, perpMag), 1);
  }
}

function selectArrow(idx) {
  if (selectedArrowIdx === idx) {
    selectedArrowIdx = -1;
  } else {
    selectedArrowIdx = idx;
  }
  updateScene();
}

function setViewMode(mode) {
  currentMode = mode;
  document.getElementById('btnUnpol').classList.toggle('active', mode === 'unpolarized');
  document.getElementById('btnAfter').classList.toggle('active', mode === 'after');
  updateScene();
}

// ═══ UI WIRING ═══
document.getElementById('filterAxisAngle').addEventListener('input', updateScene);
document.getElementById('btnUnpol').addEventListener('click', () => setViewMode('unpolarized'));
document.getElementById('btnAfter').addEventListener('click', () => setViewMode('after'));

// ═══ DEMO STEPS ═══
let _tweenRAF = null;
function tweenSlider(target, duration, cb) {
  const slider = document.getElementById('filterAxisAngle');
  const start = parseFloat(slider.value);
  const t0 = performance.now();
  if (_tweenRAF) cancelAnimationFrame(_tweenRAF);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const ease = t * (2 - t);
    slider.value = Math.round(start + (target - start) * ease);
    updateScene();
    if (t < 1) _tweenRAF = requestAnimationFrame(tick);
    else if (cb) cb();
  }
  tick();
}

function goToStep(n) {
  selectedArrowIdx = -1;
  switch (n) {
    case 0:
      setViewMode('unpolarized');
      tweenSlider(90, 400);
      break;
    case 1:
      setViewMode('after');
      tweenSlider(90, 400);
      break;
    case 2:
      setViewMode('after');
      tweenSlider(45, 600);
      break;
    case 3:
      setViewMode('after');
      tweenSlider(90, 400, () => { selectedArrowIdx = 1; updateScene(); });
      break;
  }
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('step3').addEventListener('click', () => goToStep(3));

// ═══ CAMERA ═══
setCameraView({
  projection: 'perspective',
  azimuthDeg: 32,
  elevationDeg: 16,
  rollDeg: 0,
  heightFraction: 0.66
});

// Initial state
updateScene();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

