// starburst → 8× (CylinderGeometry(0.045,0.045,0.78,8) + ConeGeometry(0.09,0.22,8)) red #cc2222, at (-1.5,0,0), rotX = i*45° in YZ plane
// E labels → addLabel at tips of arrows 0°,45°,90°,135°
// 'Random polarization' → addLabel (-1.5,1.55,0)
// 'Direction of ray (of propagation)' → addLabel (3.2,-0.55,0)
// filter disk → CircleGeometry(1.15,32) tan #f0d9a8 op0.55 + TorusGeometry(1.15,0.04,8,32) rim #e0a050, at (1,0,0) in YZ plane
// axis arrow → double-headed black #111, totalLen 2.0, at (1,0,0), rotX = π/2 - a
// transmitted arrow → double-headed red #cc2222, totalLen 1.8, at (2.8,0,0), same rotX as axis
// 'Polarizing filter' → addLabel (1.0,1.85,0) + wavy leader to disk top
// 'Axis' → addLabel (1.65,1.35,0) + wavy leader to axis tip
// 'E' transmitted → addLabel near transmitted arrow tip
// 'Polarization direction' → addLabel (3.5,1.1,0) + wavy leader
// green decomp → makeArrow #22aa44 at filter along axis direction
// grey decomp → makeArrow #999999 op0.4 at starburst perpendicular direction

// ═══ HELPERS ═══
const E_VEC_HTML = '<span style="position:relative;display:inline-block;font-weight:bold">E<span style="position:absolute;top:-0.65em;left:0.15em;font-size:0.55em;font-weight:normal">→</span></span>';

function makeArrow(length, radius, color, headLen, headRad, opacity) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: opacity ?? 1 });
  const shaftLen = Math.max(0.01, length - headLen);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 8), mat);
  shaft.position.y = shaftLen / 2;
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  head.position.y = shaftLen + headLen / 2;
  g.add(head);
  return g;
}

function makeDoubleArrow(totalLen, radius, color, headLen, headRad, opacity) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: opacity ?? 1 });
  const shaftLen = Math.max(0.01, totalLen - 2 * headLen);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 8), mat);
  g.add(shaft);
  const hUp = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  hUp.position.y = shaftLen / 2 + headLen / 2;
  g.add(hUp);
  const hDn = new THREE.Mesh(new THREE.ConeGeometry(headRad, headLen, 8), mat);
  hDn.rotation.z = Math.PI;
  hDn.position.y = -(shaftLen / 2 + headLen / 2);
  g.add(hDn);
  return g;
}

function makeWavyLeader(start, end, color) {
  const pts = [];
  const n = 24;
  const dir = new THREE.Vector3().subVectors(end, start);
  dir.normalize();
  let perp = new THREE.Vector3(0, 0, 1).cross(dir);
  if (perp.lengthSq() < 0.01) perp = new THREE.Vector3(0, 1, 0).cross(dir);
  perp.normalize();
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const p = start.clone().lerp(end, t);
    const wave = Math.sin(t * Math.PI * 4) * 0.05 * Math.sin(t * Math.PI);
    p.addScaledVector(perp, wave);
    pts.push(p);
  }
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geom, new THREE.LineBasicMaterial({ color: color ?? 0x111111 }));
}

// ═══ BUILD GEOMETRY ═══

// 1. Blue propagation ray
const rayPts = [new THREE.Vector3(-3, 0, 0), new THREE.Vector3(3.7, 0, 0)];
const rayLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(rayPts),
  new THREE.LineBasicMaterial({ color: 0x1f8fb0 })
);
scene.add(rayLine);

const rayHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.08, 0.3, 8),
  new THREE.MeshBasicMaterial({ color: 0x1f8fb0 })
);
rayHead.rotation.z = -Math.PI / 2;
rayHead.position.set(4, 0, 0);
scene.add(rayHead);

// 2. Starburst arrows (in YZ plane at x=-1.5)
const starCenter = new THREE.Vector3(-1.5, 0, 0);
const starArrows = [];
const starMats = [];
for (let i = 0; i < 8; i++) {
  const angle = i * Math.PI / 4;
  const mat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
  const arrow = makeArrow(1.0, 0.045, 0xcc2222, 0.22, 0.09);
  arrow.traverse(o => { if (o.isMesh) o.material = mat; });
  arrow.rotation.x = angle;
  arrow.position.copy(starCenter);
  scene.add(arrow);
  starArrows.push(arrow);
  starMats.push(mat);
  const deg = i * 45;
  registerInteractive(arrow, {
    title: `E-field at ${deg}°`,
    body: `This E-field vector points at ${deg}° from vertical in the transverse plane. Click to isolate it and see how the filter decomposes it into a transmitted (parallel) and absorbed (perpendicular) component. Transmitted amplitude = E₀·cos(θ).`,
    tooltip: `E at ${deg}° — click to decompose`,
    onClick: () => selectArrow(i)
  });
}

// 3. Filter disk + rim (in YZ plane at x=1.0)
const filterGroup = new THREE.Group();
const diskMat = new THREE.MeshBasicMaterial({ color: 0xf0d9a8, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
const disk = new THREE.Mesh(new THREE.CircleGeometry(1.15, 32), diskMat);
disk.rotation.y = Math.PI / 2;
filterGroup.add(disk);
const rimMat = new THREE.MeshBasicMaterial({ color: 0xe0a050, transparent: true, opacity: 1 });
const rim = new THREE.Mesh(new THREE.TorusGeometry(1.15, 0.04, 8, 32), rimMat);
rim.rotation.y = Math.PI / 2;
filterGroup.add(rim);
filterGroup.position.set(1.0, 0, 0);
scene.add(filterGroup);

// 4. Axis double-headed arrow (at filter, rotates with slider)
const axisGroup = new THREE.Group();
const axisMat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 1 });
const axisArrow = makeDoubleArrow(2.0, 0.03, 0x111111, 0.2, 0.07);
axisArrow.traverse(o => { if (o.isMesh) o.material = axisMat; });
axisGroup.add(axisArrow);
axisGroup.position.set(1.0, 0, 0);
scene.add(axisGroup);

// 5. Transmitted double-headed arrow (beyond filter, same orientation as axis)
const transGroup = new THREE.Group();
const transMat = new THREE.MeshBasicMaterial({ color: 0xcc2222, transparent: true, opacity: 1 });
