greyGroup.visible = false;
scene.add(greyGroup);

// 7. Wavy leaders
const leaderFilter = makeWavyLeader(
  new THREE.Vector3(1.0, 1.85, 0), new THREE.Vector3(1.0, 1.25, 0)
