}

addLabel('Random polarization', new THREE.Vector3(-1.5, 1.6, 0), { fontSize: '13px', bold: true });
addLabel('Direction of ray<br>(of propagation)', new THREE.Vector3(3.2, -0.55, 0), { fontSize: '12px' });
addLabel('Polarizing filter', new THREE.Vector3(1.0, 2.0, 0), { fontSize: '13px', bold: true });
addLabel('Axis', new THREE.Vector3(1.75, 1.45, 0), { fontSize: '13px', bold: true });

const lblTransE = addLabel(E_VEC_HTML, new THREE.Vector3(3.15, 0.95, 0), { fontSize: '14px', color: '#cc2222' });
const lblPolDir = addLabel('Polarization<br>direction', new THREE.Vector3(3.6, 1.2, 0), { fontSize: '12px' });

// Panel labels
addLabel('(a)', new THREE.Vector3(-1.5, -1.7, 0), { fontSize: '13px', color: '#333' });
addLabel('(b)', new THREE.Vector3(1.5, -1.7, 0), { fontSize: '13px', color: '#333' });

// ═══ STATE & UPDATE ═══
let currentMode = 'unpolarized';
let selectedArrowIdx = -1;

function getAxisDir() {
  const a = parseFloat(document.getElementById('filterAxisAngle').value) * Math.PI / 180;
  // At 90° (default): (0, sin90, cos90) = (0,1,0) = vertical ✓
  return new THREE.Vector3(0, Math.sin(a), Math.cos(a));
}

function updateScene() {
  const aDeg = parseFloat(document.getElementById('filterAxisAngle').value);
  const aRad = aDeg * Math.PI / 180;
  document.getElementById('axisAngleVal').textContent = aDeg + '°';

  // Rotate axis and transmitted arrows: rotX = π/2 - a so at a=90° rotX=0 (vertical)
  const rotAngle = Math.PI / 2 - aRad;
  axisGroup.rotation.x = rotAngle;
  transGroup.rotation.x = rotAngle;

  // Update dynamic label positions
  const dAxis = getAxisDir();
  const transTip = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 1.05);
  lblTransE.pos.copy(transTip).add(new THREE.Vector3(0.2, 0.1, 0));

  const polDirPos = new THREE.Vector3(2.8, 0, 0).addScaledVector(dAxis, 0.7).add(new THREE.Vector3(0.7, 0.35, 0));
  lblPolDir.pos.copy(polDirPos);

  // View mode: fully hide filter/transmitted in unpolarized mode
  if (currentMode === 'unpolarized') {
    starMats.forEach(m => { m.opacity = 1; });
    filterGroup.visible = false;
    transGroup.visible = false;
    axisGroup.visible = false;
    leaderFilter.visible = false;
    leaderAxis.visible = false;
    leaderPolDir.visible = false;
    lblTransE.div.style.display = 'none';
    lblPolDir.div.style.display = 'none';
    greenGroup.visible = false;
    greyGroup.visible = false;
  } else {
    filterGroup.visible = true;
    transGroup.visible = true;
    axisGroup.visible = true;
    leaderFilter.visible = true;
    leaderAxis.visible = true;
    leaderPolDir.visible = true;
    lblTransE.div.style.display = '';
    lblPolDir.div.style.display = '';
    starMats.forEach((m, i) => {
      m.opacity = (i === selectedArrowIdx) ? 1 : 0.25;
    });
    diskMat.opacity = 0.55;
    rimMat.opacity = 1;
    axisMat.opacity = 1;
    transMat.opacity = 1;
    updateDecomposition();
  }
}

function updateDecomposition() {
  if (selectedArrowIdx < 0 || currentMode !== 'after') {
    greenGroup.visible = false;
    greyGroup.visible = false;
    return;
  }

  const theta = selectedArrowIdx * Math.PI / 4;
  const dArrow = new THREE.Vector3(0, Math.cos(theta), Math.sin(theta));
  const dAxis = getAxisDir();

  const dot = dArrow.dot(dAxis);
  const parallel = dAxis.clone().multiplyScalar(dot);
  const perp = dArrow.clone().sub(parallel);
  const parallelMag = Math.abs(dot);
  const perpMag = perp.length();

  // Green arrow at filter, along axis direction
  greenGroup.visible = parallelMag > 0.02;
  if (greenGroup.visible) {
    greenGroup.position.set(1.0, 0, 0);
    const targetDir = dot >= 0 ? dAxis.clone() : dAxis.clone().negate();
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), targetDir.normalize());
    greenGroup.quaternion.copy(q);
    greenGroup.scale.set(1, Math.max(0.05, parallelMag), 1);
  }

  // Grey arrow at starburst, along perpendicular direction
  greyGroup.visible = perpMag > 0.02;
  if (greyGroup.visible) {
    greyGroup.position.copy(starCenter);
    const q2 = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), perp.clone().normalize());
    greyGroup.quaternion.copy(q2);
    greyGroup.scale.set(1, Math.max(0.05, perpMag), 1);
  }
}

function selectArrow(idx) {
  if (selectedArrowIdx === idx) {
    selectedArrowIdx = -1;
  } else {
    selectedArrowIdx = idx;
  }
  updateScene();
}

function setViewMode(mode) {
  currentMode = mode;
  document.getElementById('btnUnpol').classList.toggle('active', mode === 'unpolarized');
  document.getElementById('btnAfter').classList.toggle('active', mode === 'after');
  updateScene();
}

// ═══ UI WIRING ═══
document.getElementById('filterAxisAngle').addEventListener('input', updateScene);
document.getElementById('btnUnpol').addEventListener('click', () => setViewMode('unpolarized'));
document.getElementById('btnAfter').addEventListener('click', () => setViewMode('after'));

// ═══ DEMO STEPS ═══
let _tweenRAF = null;
function tweenSlider(target, duration, cb) {
  const slider = document.getElementById('filterAxisAngle');
  const start = parseFloat(slider.value);
  const t0 = performance.now();
  if (_tweenRAF) cancelAnimationFrame(_tweenRAF);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const ease = t * (2 - t);
    slider.value = Math.round(start + (target - start) * ease);
    updateScene();
    if (t < 1) _tweenRAF = requestAnimationFrame(tick);
    else if (cb) cb();
  }
  tick();
}

function goToStep(n) {
  selectedArrowIdx = -1;
  switch (n) {
    case 0:
      setViewMode('unpolarized');
      tweenSlider(90, 400);
      break;
    case 1:
      setViewMode('after');
      tweenSlider(90, 400);
      break;
    case 2:
      setViewMode('after');
      tweenSlider(45, 600);
      break;
    case 3:
      setViewMode('after');
      tweenSlider(90, 400, () => { selectedArrowIdx = 1; updateScene(); });
      break;
  }
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('step3').addEventListener('click', () => goToStep(3));

// ═══ CAMERA ══
// Near-front-on to match the flat 2D layout of the source figure
setCameraView({
  projection: 'perspective',
  azimuthDeg: 8,
  elevationDeg: 5,
  rollDeg: 0,
  heightFraction: 0.62
});

// Initial state
updateScene();
